dir:






































































































































	select data as id into #id from dbo.ISWIFTFunction$Split(@so_ct, ',') 

	select top 0 ma_kien,so_luong,ty_trong,tong_trong,ty_khoi,tong_khoi,id as id_bg,so_ct as so_ct_bg,line as line_bg into #detail from v61 a

	DECLARE @q NVARCHAR(4000), @id_yc int, @t_luong numeric(19,5),@t_khoi numeric(19,5),@dl_yn int, @ncc_yn int,@ma_hang varchar(32),@ten_hang nvarchar(255),@ma_dl varchar(32), @id_bg int, @so_ct_bg int

	select * into #master1 from s42 where id in (select top 1 id from #id order by id desc)
	select * into #detail1 from v42 where id in (select id from #master1)

	select  @id_yc = id_yc, @id_bg = id, @so_ct_bg = so_ct from #master1

	select * into #masteryc1 from s12 where id in (select id_yc from #master1)
	select * into #detailyc1 from v12 where id in (select Id from #masteryc1)

	if(@id_yc) <> 0
		begin
			Set @q = 'insert into #detail select ma_kien,so_luong,ty_trong,tong_trong,ty_khoi,tong_khoi,@id_bg,@so_ct_bg,line from #detailyc1'
			set @q = REPLACE(@q,'@id_bg',@id_bg)
			set @q = REPLACE(@q,'@so_ct',@so_ct_bg)
			exec(@q);
		end
	else 
		begin
			set @q = 'insert into #detail select ''CT'',1,t_tong_trong,1*t_tong_trong,t_tong_khoi,1*t_tong_khoi,id,so_ct,0 from #master1'
			exec(@q);
		end


	select a.*, k.ten_kien from #detail a left join dmkien k on a.ma_kien = k.ma_kien

	DECLARE @tma_kh table (ma_hang varchar(32), ten_hang nvarchar(256), dl_yn int, ncc_yn int)
	insert into @tma_kh select a.ma_hang, d.ten_hang, d.dl_yn, d.ncc_yn from s42 a 
	  left join vdmhangtau d on a.ma_hang =d.ma_hang 
	where a.id in (select top 1 id from #id order by id desc)

	select @dl_yn = dl_yn, @ncc_yn = ncc_yn, @ma_hang = ma_hang,@ten_hang = ten_hang, @ma_dl = ma_hang from @tma_kh

	select a.ma_noi_di,a.ma_noi_den,a.ma_kh,a.ma_nt, iif(@ncc_yn = 1, @ma_hang,'') ma_hang,iif(@dl_yn = 1, @ma_dl,'') ma_dl,
	b.ten_noi_di,c.ten_noi_den,d.ten_kh,e.ten_hang, iif(@dl_yn = 1, @ten_hang,'') ten_dl, a.ngay_hl, a.ngay_hld, a.ma_gd, id id_bg, a.id_yc, ma_ct ma_ct_bg from s42 a 
	  left join vdmcangdi b on a.ma_noi_di =b.ma_noi_di 
	  left join vdmcangden c on a.ma_noi_den =c.ma_noi_den 
	  left join dmkh d on a.ma_kh =d.ma_kh 
	  left join vdmhangtau e on a.ma_hang = e.ma_hang
	where a.id in (select top 1 id from #id order by id desc)

	drop table #id, #detail, #master1, #detail1, #masteryc1, #detailyc1









  &DefaultButton;




function filter$s612BQ2Select(p){
  this.constructor(p);
}
filter$s612BQ2Select.prototype = new DirEvent();
filter$s612BQ2Select.prototype.beforeInit = function(){
  var p = this._dir;

}


filter$s612BQ2Select.prototype.afterInit = function(){
  var p = this._dir;
  p.valForm(['ngay_ct1','ngay_ct2','id', 'ma_noi_di', 'ten_noi_di', 'ma_noi_den', 'ten_noi_den','ma_kh','ten_kh', 'ma_nt', 'unit_id'], [p.options._ngay_ct1,p.options._ngay_ct2,p.options._so_ct,p.options._ma_noi_di, p.options._ten_noi_di,p.options._ma_noi_den, p.options._ten_noi_den,p.options._ma_kh, p.options._ten_kh,  p.options._ma_nt, p.options._unit_id]);
	dir$s612BQ2SetMaster(p);

}

function dir$s612BQ2SetMaster(p) {
  p.request('ma_kh_request', '', ['id']);
}

filter$s612BQ2Select.prototype.beforeAcceptFilter = function (m2, opt, sub) {
  var p = this._dir, pa = p.options.parent, g = p.grid(), dt = g.data, master = g.ds.get(1), rErr = '';

 var fun = function(){
	dt.removeRow('[so_luong] == 0');
    pa.appendGrid(0, dt, p.valForm('xprocess') == "2", 'so_luong', 'so_luong');
	pa.calcExpressionAll(0, 'so_luong');
    pa.appendForm(master, 0);
    p._close();
  }

  if (rErr.length) {
    $.question('$VoucherRetrieveLimit', null, p, function(q, v){
      q._close();
      if (v) fun();
    });
  } else fun();


  //p._close();

  return false;
}










					select top 1 a.id_yc as [!id_yc], a.ma_kh as [!ma_kh],d.ten_kh as [!ten_kh],a.ma_hang as [!ma_hang], a.ma_noi_di as [!ma_noi_di], a.ma_noi_den as [!ma_noi_den],
					b.ten_noi_di as [!ten_noi_di],c.ten_noi_den as [!ten_noi_den], e.ten_kh as [!ten_hang],a.so_ct as [!so_ct]
					from s42 a left join vdmcangdi b on a.ma_noi_di =b.ma_noi_di left join vdmcangden c on a.ma_noi_den =c.ma_noi_den left join dmkh d on a.ma_kh =d.ma_kh left join dmkh e on a.ma_hang =e.ma_kh
					where a.id = @id
